-- Migration: 20270225000000_global_iata_airports_unification.sql
-- Sincronização e Carga Canônica do Catálogo Global de Aeroportos (7314 Aeroportos Mundiais & Nacionais)
-- Garante schema e dados completos em public.airports_global e public.ck_airports.

CREATE TABLE IF NOT EXISTS public.airports_global (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  iata_code varchar(3) UNIQUE NOT NULL,
  icao_code varchar(4),
  name text NOT NULL,
  city text NOT NULL,
  state_province text,
  country text NOT NULL,
  country_code varchar(2) NOT NULL,
  latitude numeric(10, 6),
  longitude numeric(10, 6),
  timezone text DEFAULT 'America/Sao_Paulo',
  is_commercial boolean DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.ck_airports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  iata_code varchar(3) UNIQUE NOT NULL,
  icao_code varchar(4),
  name text NOT NULL,
  city text NOT NULL,
  state_province text,
  country text NOT NULL,
  country_code varchar(2) NOT NULL,
  latitude numeric(10, 6),
  longitude numeric(10, 6),
  timezone text DEFAULT 'America/Sao_Paulo',
  is_commercial boolean DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_airports_iata ON public.airports_global(iata_code);
CREATE INDEX IF NOT EXISTS idx_airports_city ON public.airports_global(city);
CREATE INDEX IF NOT EXISTS idx_airports_country ON public.airports_global(country);
CREATE INDEX IF NOT EXISTS idx_airports_commercial ON public.airports_global(is_commercial);

CREATE INDEX IF NOT EXISTS idx_ck_airports_iata ON public.ck_airports(iata_code);
CREATE INDEX IF NOT EXISTS idx_ck_airports_city ON public.ck_airports(city);
CREATE INDEX IF NOT EXISTS idx_ck_airports_country ON public.ck_airports(country);

ALTER TABLE public.airports_global ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ck_airports ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read airports_global" ON public.airports_global;
CREATE POLICY "Public read airports_global" ON public.airports_global FOR SELECT USING (true);

DROP POLICY IF EXISTS "ck_airports_public_read" ON public.ck_airports;
CREATE POLICY "ck_airports_public_read" ON public.ck_airports FOR SELECT USING (true);

